import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-03-08","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-03-08","date":"2023-03-08T00:00:00.000Z","updated":"2023-03-09T00:00:00.000Z","tags":["Ceph","RGW","分布式存储","跟踪技术","代码重构","测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-08.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-08.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-03-08.md"};function o(s,e,n,d,p,_){return a(),i("div",null,[...e[0]||(e[0]=[t('<p>在2023年3月8日的Ceph RGW重构会议上，研发团队深入讨论了端到端跟踪技术的实现和优化问题，并就代码重构、测试策略等方面做出了重要决策。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>端到端跟踪的实现</strong>：</p><ul><li>会议重点讨论了端到端跟踪技术的通用性和特定实现问题。由于跟踪技术本身不特定于某个领域，但需要在代码中通过不同的API传递，并最终序列化到消息中。</li><li>Omri负责将跟踪信息添加到cell对象中，以便在对象进入rados时可以提取和序列化跟踪信息。</li></ul></li><li><p><strong>代码重构对跟踪实现的影响</strong>：</p><ul><li>Casey的重构工作移除了一些对cell对象的调用，这增加了跟踪信息传递的复杂性。</li><li>团队讨论了如何在rados实现中访问和传递跟踪信息，特别是在重构后如何处理cell对象和rados对象之间的关系。</li></ul></li><li><p><strong>具体实施方案的讨论</strong>：</p><ul><li>提出了几种可能的解决方案，包括将跟踪信息添加到所有API函数定义中，或者将跟踪信息作为对象的一个属性。</li><li>讨论了在rados对象中存储跟踪信息的可能性，并探讨了如何通过现有结构传递跟踪信息。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>决定在rgw rados对象类中添加跟踪信息，以便在读写路径中获得更多的覆盖率。</li><li>确认了rgw rados对象类可以从rgw cell构造，因此可以在这些类中传递跟踪信息。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续探索和实施在rgw rados对象类中添加跟踪信息的方案。</li><li>考虑使用warp等工具进行并行工作负载测试，以增强升级测试的覆盖范围。</li><li>对现有Ragweed测试进行审计，并考虑添加新的测试案例，特别是针对新功能的开发。</li></ul><ol start="4"><li><strong>代码重构与测试</strong>： <ul><li>讨论了删除不再使用的代码部分，特别是与Pub sub相关的代码。</li><li>探讨了升级测试的策略，包括使用Ragweed测试和可能的S3测试集成。</li><li>讨论了在rgw rados中添加跟踪信息的方法，并确定了后续的行动计划。</li></ul></li></ol><h3 id="会议结论" tabindex="-1">会议结论 <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论&quot;">​</a></h3><p>本次会议对Ceph RGW的端到端跟踪、代码重构和测试策略进行了深入讨论，并确定了具体的实施方案和后续行动计划，旨在提高Ceph系统在升级过程中的稳定性和可靠性。</p>',10)])])}const g=l(r,[["render",o]]);export{h as __pageData,g as default};
